<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class edit extends lib { var $abspath; public function init() { if (!$this->options->qc_static_cache_enabled) return; foreach ($this->options->qc_static_cache_post_types as $post_type) { $screen_id = $post_type == 'attachment' ? 'upload' : 'edit-'.$post_type; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_bulk_actions'), 10, 3 ); } foreach ($this->options->qc_static_cache_taxonomies as $taxonomy) { $screen_id = 'edit-' . $taxonomy; add_filter( "bulk_actions-{$screen_id}", array($this, 'add_bulk_actions') ); add_filter( "handle_bulk_actions-{$screen_id}", array($this, 'handle_taxonomies_bulk_actions'), 10, 3 ); } add_action( 'admin_notices', array($this, 'admin_notices') ); } public function add_bulk_actions($actions) { $actions['update-cache'] = __('Update Cache', $this->text_domain); $actions['remove-cache'] = __('Remove Cache', $this->text_domain); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'update-cache': foreach ( $post_ids as $post_id ) { $this->core->singular->make_cache($post_id); } $redirect_to = add_query_arg( 'bulk_update_cache', count( $post_ids ), $redirect_to ); break; case 'remove-cache': foreach ( $post_ids as $post_id ) { $this->core->remove->singular($post_id); } $redirect_to = add_query_arg( 'bulk_remove_cache', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function handle_taxonomies_bulk_actions($redirect_to, $doaction, $term_ids) { switch ($doaction) { case 'update-cache': foreach ( $term_ids as $term_id ) { $this->core->archive->make_cache($term_id, $_POST['taxonomy']); } $redirect_to = add_query_arg( 'bulk_update_taxonomies_cache', count( $term_ids ), $redirect_to ); break; case 'remove-cache': foreach ( $term_ids as $term_id ) { $this->core->remove->archive($term_id, $_POST['taxonomy']); } $redirect_to = add_query_arg( 'bulk_remove_taxonomies_cache', count( $term_ids ), $redirect_to ); break; } return $redirect_to; } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_update_cache'] ) ) { $hanler_count = intval( $_REQUEST['bulk_update_cache'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Updated %s post cache.', 'Updated %s posts cache.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } elseif ( ! empty( $_REQUEST['bulk_remove_cache'] ) ) { $hanler_count = intval( $_REQUEST['bulk_remove_cache'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Removed %s post cache.', 'Removed %s posts cache.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } elseif ( ! empty( $_REQUEST['bulk_update_taxonomies_cache'] ) ) { $hanler_count = intval( $_REQUEST['bulk_update_taxonomies_cache'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Updated %s term cache.', 'Updated %s terms cache.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } elseif ( ! empty( $_REQUEST['bulk_remove_taxonomies_cache'] ) ) { $hanler_count = intval( $_REQUEST['bulk_remove_taxonomies_cache'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Removed %s term cache.', 'Removed %s terms cache.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } } ?>